    function run(uint256 m, uint256 v) public {
        require(v <= m);
        c.mintToken(address(this), m); if (__ESBMC_reverted()) return;
        uint256 s0 = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 b0 = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool ok = c.burn(v); if (__ESBMC_reverted()) return;
