        try c.totalSupply() returns (uint256 __r) { s0 = __r; } catch { return; }
        uint256 b0;
        try c.balanceOf(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        bool ok;
        try c.burn(v) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(ok && c.totalSupply() == s0 - v && c.balanceOf(address(this)) == b0 - v);
